(10103308, 101033, 'P1-C3-L3-O08', null, 8, 'أن يعيّن الطالب تجريبيًا قيمة التسارع الناتج عن الجاذبية الأرضية g باستخدام المؤقت ذي الشريط والتمثيل البياني، ويحسب الخطأ النسبي في القيمة التجريبية.', 'أن يعيّن الطالب تجريبيًا قيمة التسارع الناتج عن الجاذبية الأرضية g باستخدام المؤقت ذي الشريط والتمثيل البياني، ويحسب الخطأ النسبي في القيمة التجريبية.', '[]'::jsonb, 'أن يعيّن الطالب تجريبيًا قيمة التسارع الناتج عن الجاذبية الأرضية g باستخدام المؤقت ذي الشريط والتمثيل البياني، ويحسب الخطأ النسبي في القيمة التجريبية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["التسارع الناتج عن الجاذبية الأرضية","الخطأ النسبي","المؤقت ذو الشريط"]'::jsonb, null, '[84,85]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). مختبر الفيزياء «التسارع الناتج عن الجاذبية الأرضية» ص84–85: أهدافه «تقيس بيانات عن السقوط الحر، ترسم منحنى ... وتستخدمه، تقارن بين قيم g في مواقع مختلفة»؛ التحليل 1–3 والاستنتاج 1–2 (حساب g والخطأ النسبي) ص85.', null, 'approved', '2026-11-16'::timestamptz),
(10104101, 101041, 'P1-C4-L1-O01', null, 1, 'أن يعرف الطالب القوة.', 'أن يعرّف الطالب القوة.', '[]'::jsonb, 'أن يعرّف الطالب القوة.', 'تشكيل «يعرّف» لإزالة اللبس بين المعرفة والتعريف، وضبط علامة الترقيم.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["القوة"]'::jsonb, null, '[95,96,124]'::jsonb, 'مغطى', 'ص96: «والقوة هي سحب أو دفع يؤثر في جسم ما»؛ من أهداف الدرس ص95 «تعرّف القوة» ومن مفرداته؛ دليل المراجعة ص124.', null, 'approved', '2026-11-16'::timestamptz),
(10104102, 101041, 'P1-C4-L1-O02', null, 2, 'أن يوضح الطالب ما يحدث لجسم ما عندما تؤثر فيه قوة.', 'أن يوضّح الطالب ما يحدث لجسم عندما تؤثر فيه قوة (تتغير سرعته المتجهة فيكتسب تسارعًا).', '[]'::jsonb, 'أن يوضّح الطالب ما يحدث لجسم عندما تؤثر فيه قوة (تتغير سرعته المتجهة فيكتسب تسارعًا).', 'تحديد الأثر المطلوب كما يقرره الكتاب (تغير السرعة المتجهة واكتساب تسارع)، وتشكيل «يوضّح».', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["القوة","التسارع","السرعة المتجهة"]'::jsonb, null, '[96,104]'::jsonb, 'مغطى', 'ص96: «وتؤدي هذه القوة المؤثرة إلى زيادة سرعة الجسم أو إبطائها أو تغيير اتجاه حركته ... عندما تؤثر قوة في جسم ما فإنها تغير سرعته المتجهة؛ أي تُكسبه تسارعًا»؛ مراجعة 13 ص104.', null, 'approved', '2026-11-16'::timestamptz),
(10104103, 101041, 'P1-C4-L1-O03', null, 3, 'أن يفرق الطالب بين النظام ومحيط النظام ( الخارجي. )', 'أن يميّز الطالب بين النظام والمحيط الخارجي.', '[]'::jsonb, 'أن يميّز الطالب بين النظام والمحيط الخارجي.', 'استخدام مصطلح الكتاب «المحيط الخارجي» بدل «محيط النظام (الخارجي.)»، وإصلاح علامات الترقيم المختلة داخل القوسين.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["النظام","المحيط الخارجي"]'::jsonb, null, '[95,96,97]'::jsonb, 'مغطى', 'ص96: «ويُطلق على هذا الجسم اسم «النظام»، وكل ما يحيط به ويؤثر فيه بقوة يسمى المحيط الخارجي» والشكل 4-1؛ ص97 الشكل 4-2؛ من مفردات الدرس ص95.', null, 'approved', '2026-11-16'::timestamptz),
(10104104, 101041, 'P1-C4-L1-O04', null, 4, 'أن يعرف الطالب قوى التلامس ( التماس. )', 'أن يعرّف الطالب قوة التلامس (التماس).', '[]'::jsonb, 'أن يعرّف الطالب قوة التلامس (التماس).', 'تشكيل «يعرّف»، وإفراد المصطلح كما في مفردات الكتاب «قوة التلامس (التماس)»، وإصلاح علامات الترقيم المختلة داخل القوسين.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["قوة التلامس (التماس)"]'::jsonb, null, '[95,96,124]'::jsonb, 'مغطى', 'ص96: «تتولد قوة التلامس (التماس) عندما يلامس جسم من المحيط الخارجي النظام، ويؤثر فيه بقوة» مع مثال اليد والكتاب؛ من مفردات الدرس ص95؛ ص124.', null, 'approved', '2026-11-16'::timestamptz),
(10104105, 101041, 'P1-C4-L1-O05', null, 5, 'أن يعرف الطالب قوة المجال.', 'أن يعرّف الطالب قوة المجال.', '[]'::jsonb, 'أن يعرّف الطالب قوة المجال.', 'تشكيل «يعرّف» لإزالة اللبس بين المعرفة والتعريف، وضبط علامة الترقيم.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["قوة المجال"]'::jsonb, null, '[96,97,124]'::jsonb, 'مغطى', 'ص96: «ويطلق على مثل هذه القوة ومثيلاتها اسم قوة المجال، وهي تؤثر في الأجسام بغض النظر عن وجود تلامس فيما بينها من عدمه» مع أمثلة الجاذبية الأرضية والقوى المغناطيسية؛ ص97 «فإن المسبب هو كتلة الأرض التي تؤثر بقوة مجال في الكتاب»؛ ص124.', null, 'approved', '2026-11-16'::timestamptz),
(10104106, 101041, 'P1-C4-L1-O06', null, 6, 'أن يستنتج الطالب العلاقة بين القوة والتسارع.', 'أن يستنتج الطالب العلاقة بين القوة المؤثرة في جسم والتسارع الذي يكتسبه.', '[]'::jsonb, 'أن يستنتج الطالب العلاقة بين القوة المؤثرة في جسم والتسارع الذي يكتسبه.', 'إيضاح طرفي العلاقة (القوة المؤثرة في الجسم وتسارعه) وضبط الترقيم.', 'صياغة', 'يعتمد بعد التعديل', 'تحليل', 'مبادئ وقوانين', '["القوة","التسارع","التناسب الطردي"]'::jsonb, null, '[98,99]'::jsonb, 'مغطى', 'ص98 «القوة والتسارع» والشكل 4-3 (الرباط المطاطي المشدود بمقدار ثابت يكسب الجسم تسارعًا ثابتًا)؛ ص99 الشكل 4-4a «ما العلاقة بين القوة والتسارع؟ العلاقة خطية؛ فكلما كانت القوة أكبر كان التسارع الناتج أكبر» و a ∝ F.', null, 'approved', '2026-11-16'::timestamptz),
(10104107, 101041, 'P1-C4-L1-O07', null, 7, 'أن يعرف الطالب النيوتن.', 'أن يعرّف الطالب النيوتن.', '[]'::jsonb, 'أن يعرّف الطالب النيوتن.', 'تشكيل «يعرّف» لإزالة اللبس بين المعرفة والتعريف، وضبط علامة الترقيم.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["النيوتن","وحدة القوة"]'::jsonb, null, '[100,109]'::jsonb, 'مغطى', 'ص100: «أي أن وحدة القوة هي 1 kg.m/s²، أو ما اصطلح على تسميته «نيوتن»، ويرمز لها بالرمز N، ويعرف بالقوة التي تؤثر في جسم كتلته 1 kg فتكسبه تسارعًا مقداره 1 m/s² في اتجاهها»؛ ص109 «kg.m/s² هي وحدة القوة (النيوتن)».', null, 'approved', '2026-11-16'::timestamptz),
(10104108, 101041, 'P1-C4-L1-O08', null, 8, 'أن يستنتج الطالب كيفية جمع القوى.', 'أن يجد الطالب القوة المحصلة لقوتين أو أكثر تؤثر في جسم في بعد واحد (في الاتجاه نفسه أو في اتجاهين متعاكسين).', '[]'::jsonb, 'أن يجد الطالب القوة المحصلة لقوتين أو أكثر تؤثر في جسم في بعد واحد (في الاتجاه نفسه أو في اتجاهين متعاكسين).', '«يستنتج كيفية جمع القوى» عامة؛ الكتاب يدرّس جمع القوى في بعد واحد لإيجاد القوة المحصلة في الحالتين (الاتجاه نفسه والاتجاهين المتعاكسين).', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'إجراءات ومهارات', '["جمع القوى","القوة المحصلة"]'::jsonb, null, '[100,101,124]'::jsonb, 'مغطى', 'ص100 «جمع القوى»: «ويطلق على مجموع المتجهات لجميع القوى التي تؤثر في جسم اسم القوة المحصلة»؛ ص101 الشكل 4-5 (b، c، d) ومسائل تدريبية 6–8؛ دليل المراجعة ص124.', null, 'approved', '2026-11-16'::timestamptz),
(10104109, 101041, 'P1-C4-L1-O09', null, 9, 'أن يعرف الطالب قانون نيوتن الثاني.', 'أن يعرّف الطالب قانون نيوتن الثاني.', '[]'::jsonb, 'أن يعرّف الطالب قانون نيوتن الثاني.', 'تشكيل «يعرّف» لإزالة اللبس بين المعرفة والتعريف، وضبط علامة الترقيم.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'مبادئ وقوانين', '["قانون نيوتن الثاني"]'::jsonb, null, '[103,124]'::jsonb, 'مغطى', 'ص103 «قانون نيوتن الثاني»: «تسارع جسم يساوي محصلة القوى المؤثرة فيه مقسومة على كتلة الجسم» a = F_المحصلة / m؛ دليل المراجعة ص124.', null, 'approved', '2026-11-16'::timestamptz),
(10104110, 101041, 'P1-C4-L1-O10', null, 10, 'أن يطبق الطالب في العلاقة الرياضية لقانون نيوتن الثاني.', 'أن يطبّق الطالب قانون نيوتن الثاني (a = F_المحصلة / m) في حل مسائل.', '[]'::jsonb, 'أن يطبّق الطالب قانون نيوتن الثاني (a = F_المحصلة / m) في حل مسائل.', 'حرف الجر «في» بعد «يطبق» زائد ويخل بالتركيب؛ وحُدد مجال التطبيق (حل المسائل) كما في أهداف الدرس.', 'لغوي', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["قانون نيوتن الثاني","القوة المحصلة"]'::jsonb, null, '[95,104,106,125]'::jsonb, 'مغطى', 'من أهداف الدرس ص95 «تطبق قانون نيوتن الثاني في حل مسائل»؛ ص104 مثال الطاولة (100.0 N ÷ 15.0 kg = 6.67 m/s²)؛ ص106 مثال 1 (الوسادة)؛ تقويم 48–49 ص125.', null, 'approved', '2026-11-16'::timestamptz),
(10104111, 101041, 'P1-C4-L1-O11', null, 11, 'أن يعرف الطالب قانون نيوتن الأول.', 'أن يعرّف الطالب قانون نيوتن الأول.', '[]'::jsonb, 'أن يعرّف الطالب قانون نيوتن الأول.', 'تشكيل «يعرّف» لإزالة اللبس بين المعرفة والتعريف، وضبط علامة الترقيم.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'مبادئ وقوانين', '["قانون نيوتن الأول"]'::jsonb, null, '[102,124]'::jsonb, 'مغطى', 'ص102 «قانون نيوتن الأول»: «وينص على أن الجسم يبقى على حالته من حيث السكون أو الحركة المنتظمة في خط مستقيم ما لم تؤثر فيه قوة محصلة تغير من حالته» والشكل 4-6؛ دليل المراجعة ص124.', null, 'approved', '2026-11-16'::timestamptz),
(10104112, 101041, 'P1-C4-L1-O12', null, 12, 'أن يعرف الطالب القصور الذاتي وعلاقته بقانون نيوتن الأول.', 'أن يعرّف الطالب القصور الذاتي، ويوضّح علاقته بقانون نيوتن الأول.', '[]'::jsonb, 'أن يعرّف الطالب القصور الذاتي، ويوضّح علاقته بقانون نيوتن الأول.', 'التركيب الأصلي يُسند فعل التعريف إلى «علاقته» أيضًا؛ أضيف فعل «يوضّح» للعلاقة، مع تشكيل «يعرّف».', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["القصور الذاتي","قانون نيوتن الأول"]'::jsonb, null, '[102,104]'::jsonb, 'مغطى', 'ص102 «القصور الذاتي»: «يسمى قانون نيوتن الأول أحيانًا قانون القصور، فهل القصور قوة؟ لا؛ فالقصور هو ممانعة الجسم لأي تغيير في حالته من حيث السكون أو الحركة»؛ مراجعة 9 و10 ص104.', null, 'approved', '2026-11-16'::timestamptz),
(10104113, 101041, 'P1-C4-L1-O13', null, 13, 'أن يطبق الطالب في قانون القصور الذاتي.', 'أن يفسّر الطالب مواقف حياتية باستخدام مفهوم القصور الذاتي وقانون نيوتن الأول (مثل اندفاع قائد المركبة إلى الأمام عند التوقف المفاجئ).', '[]'::jsonb, 'أن يفسّر الطالب مواقف حياتية باستخدام مفهوم القصور الذاتي وقانون نيوتن الأول (مثل اندفاع قائد المركبة إلى الأمام عند التوقف المفاجئ).', '«يطبق في قانون القصور الذاتي» تركيب غير سليم (حرف جر زائد) وغير محدد السلوك؛ والكتاب يسميه «قانون القصور» ويطبقه على مواقف كاندفاع قائد المركبة (الشكل 4-7).', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'مبادئ وقوانين', '["القصور الذاتي","قانون نيوتن الأول"]'::jsonb, null, '[102,104]'::jsonb, 'مغطى', 'ص102 الشكل 4-7 «يندفع قائد المركبة بشدة نحو الأمام في السيارة التي تسير بسرعة متجهة ثابتة في حالة التوقف المفاجئ»، والشكل 4-6 (الكرة الساكنة والمتدحرجة)؛ مراجعة 10 ص104 «هل يمكن أن تشعر بالقصور الذاتي لقلم رصاص أو كتاب؟».', null, 'approved', '2026-11-16'::timestamptz),
